use std::collections::HashMap;

fn two_sum(nums: Vec<i32>, target: i32) -> Option<(usize, usize)> {
    let n = nums.len();
    // Build a map from value to all of its indices (in ascending order).
    let mut map: HashMap<i32, Vec<usize>> = HashMap::new();
    for (i, &v) in nums.iter().enumerate() {
        map.entry(v).or_default().push(i);
    }

    // Helper to find the smallest index in `indices` that is > `i`
    fn first_greater(indices: &[usize], i: usize) -> Option<usize> {
        let mut l = 0;
        let mut r = indices.len();
        while l < r {
            let m = (l + r) / 2;
            if indices[m] <= i {
                l = m + 1;
            } else {
                r = m;
            }
        }
        if l < indices.len() {
            Some(indices[l])
        } else {
            None
        }
    }

    // Scan for the lexicographically smallest pair (i, j) with i < j
    // and nums[i] + nums[j] == target (without overflow).
    for i in 0..n {
        let v = nums[i];
        // Compute complement = target - v, but only if it doesn't overflow.
        if let Some(complement) = target.checked_sub(v) {
            if let Some(indices) = map.get(&complement) {
                if let Some(j) = first_greater(indices, i) {
                    // We have i < j and nums[i] + nums[j] == target
                    return Some((i, j));
                }
            }
        }
    }

    None
}

// Example usage and a simple test
fn main() {
    let nums = vec![2, 7, 11, 15];
    let target = 9;
    assert_eq!(two_sum(nums, target), Some((0, 1)));

    let nums = vec![3, 3];
    let target = 6;
    // indices (0,1) is the lexicographically smallest valid pair
    assert_eq!(two_sum(nums, target), Some((0, 1)));

    let nums = vec![1, 2, 3, -1];
    let target = 2;
    // possible pairs: (0,3)->sum=0 no, (1,2)->5 no, (0,2)->4 no, (1,3)->1 no, ...
    assert_eq!(two_sum(nums, target), None);
}